// TH14 v1.00b st02.ecl.txt::MainSub06 wave (source body 774-790) + closure.
// Source t0 = card frame OPENING_BUFFER(120). Source returns at +760; async spawn schedule to +820.
// D01/D01b pairs at source 0/120/240/360; MainSub06b on the +240 side spawns the A02 red/blue pairs.
// Source window estimate 2600 (enemy motion + fire leaves bounds well inside), TIME_LIMIT = 120+2600+4.
const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// TH14 type 18 -> TH14_BIG_BALL (GirlD01_at etSprite 18,3); type 5 -> TH14_BALL2 (GirlA01_at etSprite 5,6).
const TH14_BIG_BALL: int = 640;
const TH14_BALL2: int = 432;

// GirlD01_at EX slot1 = ACCEL(type 4): a=120, r=difficulty scalar, s=fixed direction (TH16 direction
// resolution: literal angle). Birth ANIM slot0 omitted by policy; ACCEL starts at target birth, cleared
// after 120 updates. Source r/s sampled per bullet at config time, passed by value here.
xformdef TH14_S2_ACCEL(rate: fx, dir: angle) {
    @120 set_gravity(rate * cos(dir), rate * sin(dir));
    set_gravity(0fx, 0fx);
}

// GirlD01_at (source 435-475): 100 shots, each 1 fixed-ring big bullet fired upward, ACCEL pulls it
// back down. Interval E/N/H/L = 100/40/20/10; ACCEL scalar E/N/H/L = 0.02/0.028333/0.031667/0.036667.
async sub d01_attack() {
    var rank: int = global(GVAR_RANK);
    var interval: int = 100;
    var rate: fx = 0.02fx;
    if rank == RANK_NORMAL { interval = 40; rate = 0.028333fx; }
    if rank == RANK_HARD { interval = 20; rate = 0.031667fx; }
    if rank == RANK_LUNATIC { interval = 10; rate = 0.036667fx; }
    for i in 0..100 {
        // Per-iteration RANDRAD order: accel dir first (PI/2 + RANDRAD/6), then fire dir (-PI/2 + RANDRAD/8).
        var rr_a: int = rand(65536) - 32768;
        var accel_dir: angle = 90deg + ((rr_a / 6) as angle);
        var rr_f: int = rand(65536) - 32768;
        var fire_dir: angle = -90deg + ((rr_f / 8) as angle);
        _ = fire(TH14_BIG_BALL, 3, $self_x, $self_y, 1fx, fire_dir,
                 TH14_S2_ACCEL(rate, accel_dir), none);
        wait(interval);
    }
}

// GirlD01 (source 413-433): move 22.5deg/speed3 (`moveSpeedTime` mode0 -> 0.6 over 60), wait 60, attack.
// dir carries the mirrored heading (22.5deg left, 157.5deg right via enmCreateM child mirror).
async sub d01_main(dir: angle) {
    set_invuln(65535);
    move_vel(0, dir, 3fx, EASE_LINEAR);
    move_speed(60, 0.6fx, EASE_LINEAR);
    set_hurtbox(16fx);   // setHurtbox(32,32) -> radius 16
    set_hitbox(12fx);    // setHitbox(24,24) -> radius 12
    wait(60);
    spawn d01_attack();
    loop { wait(1000); }
}

// GirlD01b (source 477-498): dive straight down 3->0.6 over 60, then head to dir at 0.6, then attack.
async sub d01b_main(dir: angle) {
    set_invuln(65535);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);      // moveVel(PI/2,3.0); mirror-invariant heading
    move_speed(60, 0.6fx, EASE_LINEAR);
    wait(60);
    move_vel(0, dir, 0.6fx, EASE_LINEAR);      // moveVel(0.3926991,0.6) mirrored
    set_hurtbox(16fx);
    set_hitbox(12fx);
    spawn d01_attack();
    loop { wait(1000); }
}

// GirlA01_at (source 157-203): aimed single ball (TH14_BALL2 color6) at the player. Initial RAND wait
// E/N 0..299, H/L 0..59; shot count / speed / interval E1.2/1: E->none, N:1@1.2/30, H:5@4.0/60, L:10@4.0/60.
async sub a01_attack() {
    var rank: int = global(GVAR_RANK);
    var iw: int = 300;
    if rank == RANK_HARD { iw = 60; }
    if rank == RANK_LUNATIC { iw = 60; }
    wait(rand(iw));
    var shots: int = 1;
    var speed: fx = 1.2fx;
    var interval: int = 30;
    if rank == RANK_HARD { shots = 5; speed = 4.0fx; interval = 60; }
    if rank == RANK_LUNATIC { shots = 10; speed = 4.0fx; interval = 60; }
    for i in 0..shots {
        _ = fire(TH14_BALL2, 6, $self_x, $self_y, speed, aim_player(), none, none);
        wait(interval);
    }
}

// GirlA02 (source 205-228): hurtbox 12 / hitbox 8, move 22.5deg speed2.4. Attack starts at frame 0 (L),
// +120 (H), +260 (N), never (E). Angle ramp is moveAngleTime(140, mode7, +0.022689281 rad/frame) ==
// +182deg constant over 140 frames; split into two <180deg linear segments (mirror flips the sign).
async sub a02_main(dir: angle, half: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24)
    set_hitbox(8fx);     // setHitbox(16,16)
    move_vel(0, dir, 2.4fx, EASE_LINEAR);
    var rank: int = global(GVAR_RANK);
    if rank == RANK_LUNATIC { spawn a01_attack(); }
    wait(120);
    if rank == RANK_HARD { spawn a01_attack(); }
    move_angle(70, $self_angle + half, EASE_LINEAR);
    wait(70);
    move_angle(70, $self_angle + half, EASE_LINEAR);
    wait(70);
    if rank == RANK_NORMAL { spawn a01_attack(); }
    loop { wait(1000); }
}

// MainSub06b (source 792-806): spawn Sub06c (delayed 100) then 12x {Red,20,Blue,20} on the right.
async sub sub06b() {
    spawn sub06c();
    for i in 0..12 {
        _ = spawn_enemy(192fx, -32fx, 120, 0, 1000, 0, a02_main(157.5deg, -91deg));
        wait(20);
        _ = spawn_enemy(192fx, -32fx, 120, 0, 1000, 0, a02_main(157.5deg, -91deg));
        wait(20);
    }
}

// MainSub06c (source 808-822): wait 100, then 12x {Red,20,Blue,20} on the left.
async sub sub06c() {
    wait(100);
    for i in 0..12 {
        _ = spawn_enemy(-192fx, -32fx, 120, 0, 1000, 0, a02_main(22.5deg, 91deg));
        wait(20);
        _ = spawn_enemy(-192fx, -32fx, 120, 0, 1000, 0, a02_main(22.5deg, 91deg));
        wait(20);
    }
}

// MainSub06 (source 774-790): the wave's creation schedule.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-224fx, 64fx, 700, 0, 1000, 0, d01_main(22.5deg));
    _ = spawn_enemy(-96fx, -32fx, 700, 0, 1000, 0, d01b_main(22.5deg));
    wait(120);
    _ = spawn_enemy(224fx, 64fx, 700, 0, 1000, 0, d01_main(157.5deg));
    _ = spawn_enemy(96fx, -32fx, 700, 0, 1000, 0, d01b_main(157.5deg));
    wait(120);
    spawn sub06b();
    _ = spawn_enemy(-224fx, 64fx, 700, 0, 1000, 0, d01_main(22.5deg));
    _ = spawn_enemy(-96fx, -32fx, 700, 0, 1000, 0, d01b_main(22.5deg));
    wait(120);
    _ = spawn_enemy(224fx, 64fx, 700, 0, 1000, 0, d01_main(157.5deg));
    _ = spawn_enemy(96fx, -32fx, 700, 0, 1000, 0, d01b_main(157.5deg));
    wait(400);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
